// GP12 to GP15: behaviour of js/play-store.js on a public page generated with a listing URL. The page is generated by the real
// template in a subprocess and served in place of /titan-plus; nothing reaches Google.
import assert from "node:assert/strict";
import { execFileSync, spawn } from "node:child_process";
import { createServer } from "node:net";
import { after, before, test } from "node:test";
import { chromium } from "playwright";

const ROOT = new URL("../..", import.meta.url).pathname;
const LISTING = "https://play.google.com/store/apps/details?id=fr.titanapp.app";
const ANDROID = "Mozilla/5.0 (Linux; Android 14; Pixel 8) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0 Mobile Safari/537.36";
const DESKTOP = "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0 Safari/537.36";
let server, browser, BASE, HTML;
before(async () => {
  HTML = execFileSync(process.execPath, ["--input-type=module", "-e",
    `import { page } from "./tools/lib/public-template.mjs"; process.stdout.write(page({ route: "/titan-plus", title: "Tarifs de test", description: "Description assez longue pour le test.", body: "<h1>Page</h1><p>Contenu de la page.</p>" }));`],
    { cwd: ROOT, env: { ...process.env, TITAN_PLAY_STORE_URL: LISTING } }).toString();
  const port = await new Promise((ok) => { const s = createServer(); s.listen(0, () => { const { port } = s.address(); s.close(() => ok(port)); }); });
  BASE = `http://127.0.0.1:${port}`;
  server = spawn(process.execPath, ["tools/serve-public.mjs", String(port)], { cwd: ROOT, stdio: "ignore" });
  for (let i = 0; i < 50; i++) { try { if ((await fetch(BASE + "/")).ok) break; } catch {} await new Promise((r) => setTimeout(r, 100)); }
  browser = await chromium.launch();
});
after(async () => { await browser?.close(); server?.kill(); });

async function open({ ua = DESKTOP, html = HTML, path = "/titan-plus", twa = false, standalone = false } = {}) {
  const context = await browser.newContext({ userAgent: ua, viewport: { width: 390, height: 844 }, serviceWorkers: "block" });
  await context.route(/^https?:\/\/(?!127\.0\.0\.1)/, (r) => r.abort("internetdisconnected"));
  if (twa) await context.addInitScript(() => localStorage.setItem("titan_twa", "1"));
  if (standalone) await context.addInitScript(() => { const mm = window.matchMedia.bind(window); window.matchMedia = (q) => (q.includes("standalone") ? { matches: true, media: q, addEventListener() {}, removeEventListener() {} } : mm(q)); });
  const page = await context.newPage();
  const errors = [];
  page.on("pageerror", (e) => errors.push(e.message));
  await page.route(BASE + "/titan-plus", (route) => route.fulfill({ contentType: "text/html", body: html }));
  await page.goto(BASE + path);
  await page.waitForLoadState("load");
  await page.waitForTimeout(150);
  return { page, context, errors };
}

test("desktop: the footer link appears with a tracked, personal-data-free referrer, and no bar", async () => {
  const { page, context, errors } = await open();
  const link = page.locator("a[data-play-store]");
  assert.equal(await link.isVisible(), true);
  const href = await link.getAttribute("href");
  assert.ok(href.startsWith(LISTING + "&referrer="));
  assert.equal(decodeURIComponent(href.split("&referrer=")[1]), "utm_source=titan-site&utm_medium=web&utm_campaign=titan-plus");
  assert.equal(await page.locator(".play-bar").count(), 0, "no bar on a computer");
  assert.deepEqual(errors, []);
  await context.close();
});

test("Android phone in a browser: a slim bar that can be dismissed, remembered, and never blocks the page", async () => {
  const { page, context, errors } = await open({ ua: ANDROID });
  const bar = page.locator(".play-bar");
  await bar.waitFor();
  assert.match(await bar.innerText(), /TITAN existe aussi sur Android/);
  assert.ok((await bar.locator("a").getAttribute("href")).startsWith(LISTING + "&referrer="));
  assert.equal(await page.locator("h1").isVisible(), true, "the page stays usable");
  const box = await bar.boundingBox();
  assert.ok(box.height < 120, "slim bar");
  await bar.getByRole("button", { name: "Masquer cette proposition" }).click();
  assert.equal(await page.locator(".play-bar").count(), 0);
  await page.reload();
  await page.waitForTimeout(200);
  assert.equal(await page.locator(".play-bar").count(), 0, "dismissal is remembered");
  assert.deepEqual(errors, []);
  await context.close();
});

test("inside the Android app, or an installed PWA, nothing about Google Play is shown", async () => {
  let r = await open({ ua: ANDROID, twa: true });
  assert.equal(await r.page.locator(".play-bar").count(), 0);
  assert.equal(await r.page.locator("a[data-play-store]").count(), 0, "the footer link is removed in the app");
  await r.context.close();
  r = await open({ ua: ANDROID, standalone: true });
  assert.equal(await r.page.locator(".play-bar").count(), 0, "no bar in an installed PWA");
  await r.context.close();
});

test("an invalid listing in the page shows nothing; the shipped pages carry no Play markup while the link is off", async () => {
  const bad = HTML.replace(LISTING, "https://play.google.com/store/apps/details?id=com.autre.app");
  const r = await open({ ua: ANDROID, html: bad });
  assert.equal(await r.page.locator(".play-bar").count(), 0);
  assert.equal(await r.page.locator("a[data-play-store]").isVisible(), false, "the link stays hidden");
  await r.context.close();
  const shipped = await open({ ua: ANDROID, html: undefined, path: "/fonctionnalites" }).catch(() => null);
  if (shipped) {
    assert.equal(await shipped.page.locator("a[data-play-store], .play-bar").count(), 0);
    await shipped.context.close();
  }
});
